import{_ as a,o as t,c as s,a0 as n}from"./chunks/framework.ChlVJx0I.js";const l=JSON.parse('{"title":"The Safe branch summary extension is dropped","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0049-drop-safe-branch-summary.md","filePath":"adr/0049-drop-safe-branch-summary.md","lastUpdated":1794522682000}'),r={name:"adr/0049-drop-safe-branch-summary.md"};function o(i,e,d,c,h,m){return t(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="the-safe-branch-summary-extension-is-dropped" tabindex="-1">The Safe branch summary extension is dropped <a class="header-anchor" href="#the-safe-branch-summary-extension-is-dropped" aria-label="Permalink to &quot;The Safe branch summary extension is dropped&quot;">​</a></h1><p>The operator asked to remove the Safe branch summary extension. It replaced pi&#39;s built-in branch summarizer on <code>/tree</code> navigation and budgeted the summary request against the Effective window divided by the Inflation factor, degrading to a soft-skip when nothing fitted, so a code-heavy branch no longer died with <code>exceed_context_size_error</code>. The operator no longer wants the replacement: pi&#39;s built-in branch summarizer handles navigation again.</p><p>Dropped: the extension (<code>extensions/safe-branch-summary/</code>), its docs page, its tests, and the <code>e2e:safe-branch-summary</code> manifest script. Moved: the Effective window and Inflation factor glossary terms that lived in the extension&#39;s section now live in the Output limits section, which with Output starvation still uses both.</p><p>This ADR supersedes <a href="/pi-extensions/adr/0025-safe-branch-summary-replaces-the-built-in.html">ADR 0025</a>. The superseded file stays in the index, marked superseded, as the record of why that design was made and what it guaranteed.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li><code>/tree</code> navigation falls back to pi&#39;s built-in branch summarizer: its summary request is no longer budgeted against the window, so a code-heavy branch can again die with <code>exceed_context_size_error</code>.</li><li>The operator&#39;s pi carries no safe-branch-summary exclusion or setting to remove; the extension read only its own <code>safeBranchSummary</code> section, which the operator does not set.</li><li>Output limits and Output starvation keep their <code>inflation</code> settings; the shared default (2.0) loses its third reader, and the Inflation factor glossary term now names the two that remain.</li></ul>',6)])])}const p=a(r,[["render",o]]);export{l as __pageData,p as default};
